/**
 * Generates static third-party provider mappings, manifests, and runtime shards.
 */

import { existsSync } from "node:fs";
import {
  copyFile,
  mkdir,
  mkdtemp,
  readFile,
  readdir,
  rename,
  rm,
  writeFile,
} from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import process from "node:process";

import { parseIconSvg } from "../lib/svg-pipeline.mjs";

const providerIds = new Set(["lucide", "phosphor", "fontawesome", "iconify"]);
const arguments_ = process.argv.slice(2);
let provider;
let checkMode = false;
for (let index = 0; index < arguments_.length; index += 1) {
  const argument = arguments_[index];
  if (argument === "--check" && !checkMode) {
    checkMode = true;
  } else if (argument === "--provider" && provider === undefined) {
    provider = arguments_[index + 1];
    index += 1;
  } else {
    throw new Error(
      `Unexpected generate-provider argument: ${String(argument)}.`,
    );
  }
}
if (!providerIds.has(provider)) {
  throw new Error(
    "--provider must be lucide, phosphor, fontawesome, or iconify.",
  );
}
const packageRoot = process.cwd();
const packageManifest = JSON.parse(
  await readFile(resolve(packageRoot, "package.json"), "utf8"),
);
if (packageManifest.name !== `@miaixz/icons-${provider}`) {
  throw new Error(
    `generate-provider.mjs must run from @miaixz/icons-${provider}.`,
  );
}
const repositoryRoot = resolve(packageRoot, "../..");
if (provider === "iconify") {
  for (const path of [
    "src/index.ts",
    "src/converter.ts",
    "src/create-iconify-provider.ts",
    "src/types.ts",
  ]) {
    if (!existsSync(resolve(packageRoot, path)))
      throw new Error(`Missing Iconify source: ${path}`);
  }
  console.log("Iconify fixed sources are valid.");
  process.exit(0);
}

const configPath = resolve(packageRoot, "provider.config.json");
const config = JSON.parse(await readFile(configPath, "utf8"));
const catalog = JSON.parse(
  await readFile(
    resolve(repositoryRoot, "packages/icons/src/assets/catalog.json"),
    "utf8",
  ),
).icons;
const header = `${await readFile(resolve(repositoryRoot, ".github/scripts/miaixz.org"), "utf8")}\n`;
const generatedNotice =
  "/**\n * @generated by .github/scripts/modules/icons/codegen/generate-provider.mjs. Do not edit.\n */\n\n";
const geometryAttributes = new Set([
  "d",
  "cx",
  "cy",
  "r",
  "rx",
  "ry",
  "x",
  "y",
  "x1",
  "x2",
  "y1",
  "y2",
  "width",
  "height",
  "points",
  "fill-rule",
]);
const shardIds = [
  "core-ui",
  "actions",
  "navigation",
  "status",
  "files",
  "editor",
  "media",
  "communication",
  "commerce",
  "devices",
  "maps",
  "data",
  "objects",
];

/**
 * Formats one generated TypeScript module.
 *
 * @param body Module body.
 * @returns Complete source text.
 */
function moduleText(body) {
  return `${header}${generatedNotice}${body.trim()}\n`;
}

/**
 * Reads one installed source package manifest.
 *
 * @param name Exact npm package name.
 * @returns Installed manifest metadata.
 */
async function sourceManifest(name) {
  return JSON.parse(
    await readFile(
      resolve(repositoryRoot, "node_modules", name, "package.json"),
      "utf8",
    ),
  );
}

/**
 * Parses trusted build-time SVG through a strict geometry-only XML reader.
 *
 * @param source Upstream SVG source.
 * @param label Source label.
 * @returns Safe fill definition.
 */
function parseFillSvg(source, label) {
  return parseIconSvg(source, "filled", label, "third-party-build");
}

/**
 * Serializes trusted upstream node data before routing it through the shared safety pipeline.
 *
 * @param {string} tag Safe SVG leaf tag.
 * @param {Record<string, unknown>} attributes Geometry attributes.
 * @returns {string} XML leaf node.
 */
function sourceNode(tag, attributes) {
  const values = Object.entries(attributes)
    .map(
      ([name, value]) =>
        `${name}="${String(value).replaceAll("&", "&amp;").replaceAll('"', "&quot;")}"`,
    )
    .join(" ");
  return `<${tag}${values === "" ? "" : ` ${values}`}/>`;
}

/**
 * Converts a Lucide node array to a safe stroke definition.
 *
 * @param iconNode Lucide public icon node export.
 * @param label Source name.
 * @returns Safe definition.
 */
function fromLucide(iconNode, label) {
  if (!Array.isArray(iconNode) || iconNode.length === 0)
    throw new Error(`${label}: missing __iconNode.`);
  const nodes = iconNode.map(([tag, rawAttributes]) => {
    if (
      ![
        "path",
        "circle",
        "ellipse",
        "line",
        "polyline",
        "polygon",
        "rect",
      ].includes(tag)
    ) {
      throw new Error(`${label}: unsupported node ${String(tag)}.`);
    }
    const attributes = Object.fromEntries(
      Object.entries(rawAttributes).filter(
        ([name]) => name !== "key" && geometryAttributes.has(name),
      ),
    );
    return { tag, attributes };
  });
  const source = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${nodes.map((node) => sourceNode(node.tag, node.attributes)).join("")}</svg>`;
  return parseIconSvg(source, "outline", label, "third-party-build");
}

/**
 * Converts one Font Awesome icon definition to safe fill geometry.
 *
 * @param definition Font Awesome icon definition.
 * @param label Source name.
 * @returns Safe definition.
 */
function fromFontAwesome(definition, label) {
  const icon = definition?.icon;
  if (!Array.isArray(icon) || icon.length !== 5)
    throw new Error(`${label}: invalid icon tuple.`);
  const [width, height, , , paths] = icon;
  const values = Array.isArray(paths) ? paths : [paths];
  if (!values.every((path) => typeof path === "string" && path.length > 0)) {
    throw new Error(`${label}: invalid path data.`);
  }
  const source = `<svg viewBox="0 0 ${width} ${height}" fill="currentColor">${values.map((d) => sourceNode("path", { d })).join("")}</svg>`;
  return parseIconSvg(source, "filled", label, "third-party-build");
}

const sourceMetadata = [];
for (const name of config.sourcePackages) {
  const manifest = await sourceManifest(name);
  const expected = packageManifest.devDependencies[name];
  if (manifest.version !== expected)
    throw new Error(`${name} installed version does not match ${expected}.`);
  sourceMetadata.push({
    packageName: name,
    packageVersion: manifest.version,
    license: manifest.license,
  });
}

let sourceTargets;
if (provider === "lucide") {
  const imports = (await import("lucide-react/dynamicIconImports.mjs")).default;
  sourceTargets = {
    outline: new Map(
      await Promise.all(
        Object.entries(imports).map(async ([name, loader]) => {
          const module = await loader();
          return [name, fromLucide(module.__iconNode, `lucide:${name}`)];
        }),
      ),
    ),
  };
} else if (provider === "phosphor") {
  const sourceRoot = resolve(
    repositoryRoot,
    "node_modules/@phosphor-icons/core/assets",
  );
  sourceTargets = { outline: new Map(), filled: new Map() };
  for (const [variant, directory] of [
    ["outline", "regular"],
    ["filled", "fill"],
  ]) {
    for (const file of await readdir(resolve(sourceRoot, directory))) {
      if (!file.endsWith(".svg")) continue;
      const name = file.replace(/-fill\.svg$/u, "").replace(/\.svg$/u, "");
      const source = await readFile(
        resolve(sourceRoot, directory, file),
        "utf8",
      );
      sourceTargets[variant].set(
        name,
        parseFillSvg(source, `phosphor:${directory}/${file}`),
      );
    }
  }
} else {
  const regular = await import("@fortawesome/free-regular-svg-icons");
  const solid = await import("@fortawesome/free-solid-svg-icons");
  sourceTargets = { outline: new Map(), filled: new Map() };
  for (const [variant, module] of [
    ["outline", regular],
    ["filled", solid],
  ]) {
    const seen = new Set();
    for (const value of Object.values(module)) {
      if (
        !value ||
        typeof value !== "object" ||
        !Array.isArray(value.icon) ||
        seen.has(value)
      )
        continue;
      seen.add(value);
      const definition = fromFontAwesome(
        value,
        `fontawesome:${value.iconName}`,
      );
      sourceTargets[variant].set(value.iconName, definition);
      for (const alias of value.icon[2])
        if (typeof alias === "string")
          sourceTargets[variant].set(alias, definition);
    }
  }
}

const mapping = {};
const unsupported = [];
const shardDefinitions = new Map(shardIds.map((id) => [id, {}]));
for (const entry of catalog) {
  const targetName = config.overrides[entry.name] ?? entry.name;
  const target = {};
  const shardId = entry.tier === "core" ? "core-ui" : entry.category;
  for (const variant of config.variants) {
    const definition = sourceTargets[variant]?.get(targetName);
    if (definition === undefined) continue;
    target[variant] = `${shardId}/${targetName}`;
    shardDefinitions.get(shardId)[`${targetName}:${variant}`] = definition;
  }
  if (Object.keys(target).length === 0) unsupported.push(entry.name);
  else mapping[entry.name] = target;
}
unsupported.sort((left, right) => left.localeCompare(right));
if (JSON.stringify(config.unsupported) !== JSON.stringify(unsupported)) {
  throw new Error(
    `${provider} unsupported list is stale; review provider.config.json explicitly.`,
  );
}

const coverage = {};
for (const variant of config.variants) {
  const counts = { core: 0, extended: 0, compat: 0, total: 0 };
  for (const entry of catalog) {
    if (mapping[entry.name]?.[variant] === undefined) continue;
    counts[entry.tier] += 1;
    counts.total += 1;
  }
  coverage[variant] = counts;
}
const exportPrefix = provider === "fontawesome" ? "fontAwesome" : provider;
const expected = new Map();
expected.set(
  "mapping.ts",
  moduleText(
    `import type { GeneratedProviderMapping } from "./types.js";\nexport const mapping: GeneratedProviderMapping = Object.freeze(${JSON.stringify(mapping, null, 2)});`,
  ),
);
expected.set(
  "manifest.ts",
  moduleText(
    `import type { IconProviderManifest } from "@miaixz/icons/provider";\nexport const ${exportPrefix}Manifest = Object.freeze(${JSON.stringify({ schemaVersion: 2, id: provider, packageName: packageManifest.name, packageVersion: packageManifest.version, source: "third-party", license: packageManifest.license, sources: sourceMetadata, coverage, variants: config.variants, opticalSizes: config.opticalSizes }, null, 2)} as const satisfies IconProviderManifest);`,
  ),
);
for (const [id, definitions] of shardDefinitions) {
  if (Object.keys(definitions).length === 0) continue;
  const viewBoxes = [
    ...new Set(
      Object.values(definitions).map((definition) => definition.viewBox),
    ),
  ];
  const tags = [
    "path",
    "circle",
    "ellipse",
    "line",
    "polyline",
    "polygon",
    "rect",
  ];
  const attributes = [
    "d",
    "cx",
    "cy",
    "r",
    "rx",
    "ry",
    "x",
    "y",
    "x1",
    "x2",
    "y1",
    "y2",
    "width",
    "height",
    "points",
    "fillRule",
  ];
  const encoded = Object.fromEntries(
    Object.entries(definitions).map(([name, definition]) => [
      name,
      [
        viewBoxes.indexOf(definition.viewBox),
        definition.paint === "stroke" ? 0 : 1,
        definition.nodes.map((node) => [
          tags.indexOf(node.tag),
          Object.entries(node.attributes).map(([key, value]) => [
            attributes.indexOf(key),
            value,
          ]),
        ]),
      ],
    ]),
  );
  expected.set(
    `shard-${id}.ts`,
    moduleText(
      `import type { EncodedDefinition } from "./types.js";\nexport const viewBoxes = Object.freeze(${JSON.stringify(viewBoxes)});\nexport const definitions: Readonly<Record<string, EncodedDefinition>> = Object.freeze(${JSON.stringify(encoded, null, 2)});`,
    ),
  );
}
expected.set(
  "generation-report.json",
  `${JSON.stringify({ schemaVersion: 1, provider, mappedCanonicalNames: Object.keys(mapping).length, unsupportedCanonicalNames: unsupported.length, coverage, shards: Object.fromEntries([...shardDefinitions].map(([id, values]) => [id, Object.keys(values).length]).filter(([, count]) => count > 0)) }, null, 2)}\n`,
);

const generatedPattern =
  /^(?:mapping|manifest|generation-report)\.(?:ts|json)$|^shard-[a-z0-9-]+\.ts$/u;
const existing = (await readdir(resolve(packageRoot, "src"))).filter((name) =>
  generatedPattern.test(name),
);
const stagingRoot = await mkdtemp(join(tmpdir(), `miaixz-icons-${provider}-`));
try {
  for (const [name, content] of expected)
    await writeFile(resolve(stagingRoot, name), content);
  if (
    process.env.NODE_ENV === "test" &&
    process.env.MIAIXZ_ICON_GENERATOR_FAILURE === "after-stage"
  ) {
    throw new Error("Injected provider generator failure after staging.");
  }
  const failures = [];
  if (checkMode) {
    for (const name of expected.keys()) {
      const official = resolve(packageRoot, "src", name);
      const staged = resolve(stagingRoot, name);
      if (
        !existsSync(official) ||
        (await readFile(official, "utf8")) !== (await readFile(staged, "utf8"))
      ) {
        failures.push(name);
      }
    }
    failures.push(...existing.filter((name) => !expected.has(name)));
  } else {
    for (const name of expected.keys()) {
      const official = resolve(packageRoot, "src", name);
      const pending = resolve(dirname(official), `.${name}.${process.pid}.tmp`);
      await mkdir(dirname(official), { recursive: true });
      try {
        await copyFile(resolve(stagingRoot, name), pending);
        await rename(pending, official);
      } finally {
        await rm(pending, { force: true });
      }
    }
    for (const name of existing) {
      if (!expected.has(name))
        await rm(resolve(packageRoot, "src", name), { force: true });
    }
  }
  if (failures.length > 0) {
    throw new Error(
      `${provider} generated files are stale: ${failures.sort().join(", ")}`,
    );
  }
} finally {
  await rm(stagingRoot, { force: true, recursive: true });
}
console.log(
  checkMode
    ? `${provider} generated files are current.`
    : `Generated ${expected.size} ${provider} files.`,
);
